    """Partition 8-cells into 2x2 squares and 3-cell Ls, then encode tile types."""
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Each candidate is (cells, output color). L color identifies its missing corner.
    candidates = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if square <= occupied:
                candidates.append((square, 1))
            for missing, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4)]:
                cells = square - {missing}
                if cells <= occupied:
                    candidates.append((cells, color))

    by_cell = {p: [] for p in occupied}
    for candidate in candidates:
        for p in candidate[0]:
            by_cell[p].append(candidate)

    def search(remaining):
        if not remaining:
